// Ice Spin Deluxe — Spine FX layer (skeletons generated by
// scripts/ice_spin_deluxe_fx.py into img/ice-spin-deluxe/fx/).
//
// Two WebGL canvases sandwich the DOM stage, because one canvas can't sit both
// behind the cabinet and in front of it:
//   #fxBack  (under .stage)  — bg_desk / bg_mob: aurora, searchlights, snow;
//   #fxFront (over .stage)   — frame (bulbs, halo, sweep), logo (the logo
//                              itself — the DOM <img> is hidden once it's up),
//                              winlines (one fresh instance per shown line).
// Every instance is anchored to its DOM element (SpineInstance.anchorEl), so
// CSS stays the only source of layout truth on both orientations.
//
// If WebGL or any asset fails, IceFx.ready stays false and slot.js keeps its
// CSS logo glow + SVG win line.

(function () {
  const ROOT = 'img/ice-spin-deluxe/fx';
  const BOX = {
    bg_desk: { x: -800, y: -500, width: 1600, height: 1000 },
    bg_mob: { x: -390, y: -540, width: 780, height: 1080 },
    frame: { x: -836, y: -470.5, width: 1672, height: 941 },
    logo: { x: -818.5, y: -264, width: 1637, height: 528 },
    winlines: { x: -518.5, y: -320, width: 1037, height: 640 },
  };

  let back = null;
  let front = null;
  const res = {};
  let bgInst = null;
  let bgVariant = null;
  let frameInst = null;
  let logoInst = null;
  let lineInst = null;
  let lineShown = 0;
  let winOn = false;

  const IceFx = { ready: false };

  function isMobile() {
    return window.matchMedia('(orientation: portrait)').matches;
  }

  function load(stage, name) {
    return SpineEngine.SpineResource.load(stage.assetManager, `${ROOT}/${name}`, { premultipliedAlpha: true })
      .then((r) => { res[name] = r; return r; });
  }

  function make(name, anchorEl) {
    const inst = res[name].createInstance();
    inst.anchorEl = anchorEl;
    inst.fit = 1;
    inst.boundsOverride = BOX[name];
    return inst;
  }

  function mountBg() {
    const v = isMobile() ? 'bg_mob' : 'bg_desk';
    if (v === bgVariant || !res[v]) return;
    if (bgInst) back.removeBase(bgInst);
    bgVariant = v;
    bgInst = make(v, document.getElementById('stage'));
    bgInst.play('idle', true);
    back.addBase(bgInst);
  }

  IceFx.load = function load_() {
    if (!window.spine || !window.SpineEngine) return Promise.resolve(false);
    try {
      back = new SpineEngine.SpineStage(document.getElementById('fxBack'));
      front = new SpineEngine.SpineStage(document.getElementById('fxFront'));
    } catch (err) {
      console.warn('[ice-fx] no WebGL — CSS fallback', err);
      return Promise.resolve(false);
    }
    return Promise.all([
      load(back, isMobile() ? 'bg_mob' : 'bg_desk'),
      load(front, 'frame'),
      load(front, 'logo'),
      load(front, 'winlines'),
    ]).then(() => {
      IceFx.ready = true;
      mountBg();
      frameInst = make('frame', document.querySelector('.cabinet'));
      frameInst.play('idle', true);
      front.addBase(frameInst);
      logoInst = make('logo', document.querySelector('.logo'));
      logoInst.play('idle', true);
      front.addBase(logoInst);
      document.body.classList.add('fx-ready');
      // the other orientation's background loads in the background
      load(back, isMobile() ? 'bg_desk' : 'bg_mob').catch(() => {});
      window.addEventListener('resize', () => {
        const v = isMobile() ? 'bg_mob' : 'bg_desk';
        if (res[v]) mountBg();
        else load(back, v).then(mountBg).catch(() => {});
      });
      return true;
    }).catch((err) => {
      console.warn('[ice-fx] assets failed — CSS fallback', err);
      return false;
    });
  };

  // Frame + logo: `win` loop while a win is on screen, `idle` otherwise.
  IceFx.setWin = function setWin(on) {
    if (!IceFx.ready || on === winOn) return;
    winOn = on;
    const clip = on ? 'win' : 'idle';
    frameInst.play(clip, true);
    logoInst.play(clip, true);
  };

  // Payline 1..5 (index into PAYLINE_ROWS + 1). Re-showing the line already on
  // screen keeps its loop running instead of restarting the draw-in.
  IceFx.showLine = function showLine(n) {
    if (!IceFx.ready) return false;
    if (n === lineShown && lineInst) return true;
    IceFx.hideLine();
    // A fresh instance every time: the setup pose has every line hidden, so
    // nothing from the previous line can linger.
    lineInst = make('winlines', document.getElementById('reel'));
    lineInst.play(`line${n}_in`, false);
    lineInst.queue(`line${n}_loop`, true);
    lineShown = n;
    front.addOverlay(lineInst);
    return true;
  };

  IceFx.hideLine = function hideLine() {
    if (lineInst) front.removeOverlay(lineInst);
    lineInst = null;
    lineShown = 0;
  };

  window.IceFx = IceFx;
})();
